changes.old:
static bool HandleGoQuestCommand(ChatHandler* handler, char const* args)
{
    if (!*args)
        return false;
    Player* player = handler->GetSession()->GetPlayer();
    char* id = handler->extractKeyFromLink((char*)args, "Hquest");
    if (!id)
        return false;
    uint32 questID = atoi(id);
    if (!questID)
        return false;
    if (!sQuestDataStore->GetQuestTemplate(questID))
    {
        handler->PSendSysMessage(LANG_COMMAND_QUEST_NOTFOUND, questID);
        handler->SetSentErrorMessage(true);
        return false;
    }
    float x, y, z;
    uint32 mapId;
    if (QuestPOIVector const* poiData = sQuestDataStore->GetQuestPOIVector(questID))
    {
        for (auto data = poiData->begin(); data != poiData->end(); ++data)
        {
            mapId = data->MapID;
            for (auto points = data->points.begin(); points != data->points.end(); ++points)
            {
                x = points->X;
                y = points->Y;
                if (Map const* map = sMapMgr->CreateBaseMap(mapId))
                    z = std::max(map->GetHeight(x, y, MAX_HEIGHT), map->GetWaterLevel(x, y));
                break;
            }
        }
    }
    else
    {
        handler->PSendSysMessage(LANG_COMMAND_QUEST_NOTFOUND, questID);
        handler->SetSentErrorMessage(true);
        return false;
    }
    if (!MapManager::IsValidMapCoord(mapId, x, y, z) || sObjectMgr->IsTransportMap(mapId))
    {
        handler->PSendSysMessage(LANG_INVALID_TARGET_COORD, x, y, mapId);
        handler->SetSentErrorMessage(true);
        return false;
    }
    // stop flight if need
    if (player->isInFlight())
    {
        player->GetMotionMaster()->MovementExpired();
        player->CleanupAfterTaxiFlight();
    }
    // save only in non-flight case
    else
        player->SaveRecallPosition();
    player->TeleportTo(mapId, x, y, z, 0.0f);
    return true;
}

changes.new:
static bool HandleGoQuestCommand(ChatHandler* handler, char const* args)
{
    if (!*args)
        return false;
    Player* player = handler->GetSession()->GetPlayer();
    char* id = handler->extractKeyFromLink((char*)args, "Hquest");
    if (!id)
        return false;
    uint32 questID;
    if (!Trinity::ParseCommandInteger(id, questID) || !questID)
        return false;
    if (!sQuestDataStore->GetQuestTemplate(questID))
    {
        handler->PSendSysMessage(LANG_COMMAND_QUEST_NOTFOUND, questID);
        handler->SetSentErrorMessage(true);
        return false;
    }
    float x = 0.0f, y = 0.0f, z = 0.0f;
    uint32 mapId = 0;
    bool found = false;
    if (QuestPOIVector const* poiData = sQuestDataStore->GetQuestPOIVector(questID))
    {
        for (auto const& data : *poiData)
        {
            if (data.points.empty())
                continue;
            auto const& point = data.points.front();
            if (!MapManager::IsValidMapCoord(data.MapID, point.X, point.Y) || sObjectMgr->IsTransportMap(data.MapID))
                continue;
            Map const* map = sMapMgr->CreateBaseMap(data.MapID);
            if (!map)
                continue;
            float height = std::max(map->GetHeight(point.X, point.Y, MAX_HEIGHT), map->GetWaterLevel(point.X, point.Y));
            if (!MapManager::IsValidMapCoord(data.MapID, point.X, point.Y, height))
                continue;
            // Retain the last authored usable POI as one coherent pose.
            mapId = data.MapID;
            x = point.X;
            y = point.Y;
            z = height;
            found = true;
        }
    }
    if (!found)
    {
        handler->PSendSysMessage(LANG_COMMAND_QUEST_NOTFOUND, questID);
        handler->SetSentErrorMessage(true);
        return false;
    }
    if (!MapManager::IsValidMapCoord(mapId, x, y, z) || sObjectMgr->IsTransportMap(mapId))
    {
        handler->PSendSysMessage(LANG_INVALID_TARGET_COORD, x, y, mapId);
        handler->SetSentErrorMessage(true);
        return false;
    }
    // stop flight if need
    if (player->isInFlight())
    {
        player->GetMotionMaster()->MovementExpired();
        player->CleanupAfterTaxiFlight();
    }
    // save only in non-flight case
    else
        player->SaveRecallPosition();
    return player->TeleportTo(mapId, x, y, z, 0.0f);
}

changes.old:
static bool HandleWpShowCommand(ChatHandler* handler, const char* args)
{
    if (!*args)
        return false;

    // first arg: on, off, first, last
    char* show_str = strtok((char*)args, " ");
    if (!show_str)
        return false;

    // second arg: GUID (optional, if a creature is selected)
    char* guid_str = strtok((char*)NULL, " ");

    uint32 pathid = 0;
    Creature* target = handler->getSelectedCreature();

    // Did player provide a PathID?

    if (!guid_str)
    {
        // No PathID provided
        // -> Player must have selected a creature

        if (!target)
        {
            handler->SendSysMessage(LANG_SELECT_CREATURE);
            handler->SetSentErrorMessage(true);
            return false;
        }

        pathid = target->GetWaypointPath();
    }
    else
    {
        // PathID provided
        // Warn if player also selected a creature
        // -> Creature selection is ignored <-
        if (target)
            handler->SendSysMessage(LANG_WAYPOINT_CREATSELECTED);

        pathid = atoi((char*)guid_str);
    }

    std::string show = show_str;

    //handler->PSendSysMessage("wpshow - show: %s", show);

    // Show info for the selected waypoint
    if (show == "info")
    {
        // Check if the user did specify a visual waypoint
        if (target->GetEntry() != VISUAL_WAYPOINT)
        {
            handler->PSendSysMessage(LANG_WAYPOINT_VP_SELECT);
            handler->SetSentErrorMessage(true);
            return false;
        }

        WorldDatabasePreparedStatement* stmt = WorldDatabase.GetPreparedStatement(WORLD_SEL_WAYPOINT_DATA_ALL_BY_WPGUID);

        stmt->setUInt64(0, target->GetGUID().GetGUIDLow());

        PreparedQueryResult result = WorldDatabase.Query(stmt);

        if (!result)
        {
            handler->SendSysMessage(LANG_WAYPOINT_NOTFOUNDDBPROBLEM);
            return true;
        }

        handler->SendSysMessage("|cff00ffffDEBUG: wp show info:|r");
        do
        {
            Field* fields = result->Fetch();
            pathid                  = fields[0].GetUInt32();
            uint32 point            = fields[1].GetUInt32();
            uint32 delay            = fields[2].GetUInt32();
            uint32 flag             = fields[3].GetUInt32();
            uint32 ev_id            = fields[4].GetUInt32();
            uint32 ev_chance        = fields[5].GetUInt32();

            handler->PSendSysMessage("|cff00ff00Show info: for current point: |r|cff00ffff%u|r|cff00ff00, Path ID: |r|cff00ffff%u|r", point, pathid);
            handler->PSendSysMessage("|cff00ff00Show info: delay: |r|cff00ffff%u|r", delay);
            handler->PSendSysMessage("|cff00ff00Show info: Move flag: |r|cff00ffff%u|r", flag);
            handler->PSendSysMessage("|cff00ff00Show info: Waypoint event: |r|cff00ffff%u|r", ev_id);
            handler->PSendSysMessage("|cff00ff00Show info: Event chance: |r|cff00ffff%u|r", ev_chance);
        }
        while (result->NextRow());

        return true;
    }

    if (show == "on")
    {
        WorldDatabasePreparedStatement* stmt = WorldDatabase.GetPreparedStatement(WORLD_SEL_WAYPOINT_DATA_POS_BY_ID);

        stmt->setUInt32(0, pathid);

        PreparedQueryResult result = WorldDatabase.Query(stmt);

        if (!result)
        {
            handler->SendSysMessage("|cffff33ffPath no found.|r");
            handler->SetSentErrorMessage(true);
            return false;
        }

        handler->PSendSysMessage("|cff00ff00DEBUG: wp on, PathID: |cff00ffff%u|r", pathid);

        // Delete all visuals for this NPC
        stmt = WorldDatabase.GetPreparedStatement(WORLD_SEL_WAYPOINT_DATA_WPGUID_BY_ID);

        stmt->setUInt32(0, pathid);

        PreparedQueryResult result2 = WorldDatabase.Query(stmt);

        if (result2)
        {
            bool hasError = false;
            do
            {
                Field* fields = result2->Fetch();
                uint32 wpguid = fields[0].GetUInt64();
                Player* chr = handler->GetSession()->GetPlayer();

                Creature* creature = handler->GetSession()->GetPlayer()->GetMap()->GetCreature(ObjectGuid::Create<HighGuid::Creature>(chr->GetMapId(), VISUAL_WAYPOINT, wpguid));

                if (!creature)
                {
                    handler->PSendSysMessage(LANG_WAYPOINT_NOTREMOVED, wpguid);
                    hasError = true;

                    WorldDatabasePreparedStatement* stmt = WorldDatabase.GetPreparedStatement(WORLD_DEL_CREATURE);

                    stmt->setUInt64(0, wpguid);

                    WorldDatabase.Execute(stmt);
                }
                else
                {
                    creature->CombatStop();
                    creature->DeleteFromDB();
                    creature->AddObjectToRemoveList();
                }

            }
            while (result2->NextRow());

            if (hasError)
            {
                handler->PSendSysMessage(LANG_WAYPOINT_TOOFAR1);
                handler->PSendSysMessage(LANG_WAYPOINT_TOOFAR2);
                handler->PSendSysMessage(LANG_WAYPOINT_TOOFAR3);
            }
        }

        do
        {
            Field* fields = result->Fetch();
            uint32 point    = fields[0].GetUInt32();
            float x         = fields[1].GetFloat();
            float y         = fields[2].GetFloat();
            float z         = fields[3].GetFloat();

            uint32 id = VISUAL_WAYPOINT;

            Player* chr = handler->GetSession()->GetPlayer();
            Map* map = chr->GetMap();
            float o = chr->GetOrientation();

            Creature* wpCreature = new Creature;
            if (!wpCreature->Create(sObjectMgr->GetGenerator<HighGuid::Creature>()->Generate(), map, chr->GetPhaseMgr().GetPhaseMaskForSpawn(), id, 0, 0, x, y, z, o))
            {
                handler->PSendSysMessage(LANG_WAYPOINT_VP_NOTCREATED, id);
                delete wpCreature;
                return false;
            }

            // Set "wpguid" column to the visual waypoint
            WorldDatabasePreparedStatement* stmt = WorldDatabase.GetPreparedStatement(WORLD_UPD_WAYPOINT_DATA_WPGUID);

            stmt->setInt64(0, wpCreature->GetGUID().GetGUIDLow());
            stmt->setUInt32(1, pathid);
            stmt->setUInt32(2, point);

            WorldDatabase.Execute(stmt);

            wpCreature->SaveToDB(map->GetId(), (UI64LIT(1) << map->GetSpawnMode()), chr->GetPhaseMgr().GetPhaseMaskForSpawn());
            // To call _LoadGoods(); _LoadQuests(); CreateTrainerSpells();
            if (!wpCreature->LoadCreatureFromDB(wpCreature->GetDBTableGUIDLow(), map))
            {
                handler->PSendSysMessage(LANG_WAYPOINT_VP_NOTCREATED, id);
                delete wpCreature;
                return false;
            }

            if (target)
            {
                wpCreature->SetDisplayId(target->GetDisplayId());
                wpCreature->SetObjectScale(0.5f);
                wpCreature->SetLevel(point > STRONG_MAX_LEVEL ? STRONG_MAX_LEVEL : point);
            }
        }
        while (result->NextRow());

        handler->SendSysMessage("|cff00ff00Showing the current creature's path.|r");
        return true;
    }

    if (show == "first")
    {
        handler->PSendSysMessage("|cff00ff00DEBUG: wp first, GUID: %u|r", pathid);

        WorldDatabasePreparedStatement* stmt = WorldDatabase.GetPreparedStatement(WORLD_SEL_WAYPOINT_DATA_POS_FIRST_BY_ID);
        stmt->setUInt32(0, pathid);
        PreparedQueryResult result = WorldDatabase.Query(stmt);

        if (!result)
        {
            handler->PSendSysMessage(LANG_WAYPOINT_NOTFOUND, pathid);
            handler->SetSentErrorMessage(true);
            return false;
        }

        Field* fields = result->Fetch();
        float x         = fields[0].GetFloat();
        float y         = fields[1].GetFloat();
        float z         = fields[2].GetFloat();
        uint32 id = VISUAL_WAYPOINT;

        Player* chr = handler->GetSession()->GetPlayer();
        float o = chr->GetOrientation();
        Map* map = chr->GetMap();

        Creature* creature = new Creature;
        if (!creature->Create(sObjectMgr->GetGenerator<HighGuid::Creature>()->Generate(), map, chr->GetPhaseMgr().GetPhaseMaskForSpawn(), id, 0, 0, x, y, z, o))
        {
            handler->PSendSysMessage(LANG_WAYPOINT_VP_NOTCREATED, id);
            delete creature;
            return false;
        }

        creature->SaveToDB(map->GetId(), (UI64LIT(1) << map->GetSpawnMode()), chr->GetPhaseMgr().GetPhaseMaskForSpawn());
        if (!creature->LoadCreatureFromDB(creature->GetDBTableGUIDLow(), map))
        {
            handler->PSendSysMessage(LANG_WAYPOINT_VP_NOTCREATED, id);
            delete creature;
            return false;
        }

        if (target)
        {
            creature->SetDisplayId(target->GetDisplayId());
            creature->SetObjectScale(0.5f);
        }

        return true;
    }

    if (show == "last")
    {
        handler->PSendSysMessage("|cff00ff00DEBUG: wp last, PathID: |r|cff00ffff%u|r", pathid);

        WorldDatabasePreparedStatement* stmt = WorldDatabase.GetPreparedStatement(WORLD_SEL_WAYPOINT_DATA_POS_LAST_BY_ID);
        stmt->setUInt32(0, pathid);
        PreparedQueryResult result = WorldDatabase.Query(stmt);

        if (!result)
        {
            handler->PSendSysMessage(LANG_WAYPOINT_NOTFOUNDLAST, pathid);
            handler->SetSentErrorMessage(true);
            return false;
        }
        Field* fields = result->Fetch();
        float x = fields[0].GetFloat();
        float y = fields[1].GetFloat();
        float z = fields[2].GetFloat();
        float o = fields[3].GetFloat();
        uint32 id = VISUAL_WAYPOINT;

        Player* chr = handler->GetSession()->GetPlayer();
        Map* map = chr->GetMap();

        Creature* creature = new Creature;
        if (!creature->Create(sObjectMgr->GetGenerator<HighGuid::Creature>()->Generate(), map, chr->GetPhaseMgr().GetPhaseMaskForSpawn(), id, 0, 0, x, y, z, o))
        {
            handler->PSendSysMessage(LANG_WAYPOINT_NOTCREATED, id);
            delete creature;
            return false;
        }

        creature->SaveToDB(map->GetId(), (UI64LIT(1) << map->GetSpawnMode()), chr->GetPhaseMgr().GetPhaseMaskForSpawn());
        if (!creature->LoadCreatureFromDB(creature->GetDBTableGUIDLow(), map))
        {
            handler->PSendSysMessage(LANG_WAYPOINT_NOTCREATED, id);
            delete creature;
            return false;
        }

        if (target)
        {
            creature->SetDisplayId(target->GetDisplayId());
            creature->SetObjectScale(0.5f);
        }

        return true;
    }

    if (show == "off")
    {
        WorldDatabasePreparedStatement* stmt = WorldDatabase.GetPreparedStatement(WORLD_SEL_CREATURE_BY_ID);
        stmt->setUInt32(0, 1);
        PreparedQueryResult result = WorldDatabase.Query(stmt);

        if (!result)
        {
            handler->SendSysMessage(LANG_WAYPOINT_VP_NOTFOUND);
            handler->SetSentErrorMessage(true);
            return false;
        }
        bool hasError = false;
        do
        {
            Field* fields = result->Fetch();
            uint32 guid = fields[0].GetUInt64();
            Player* chr = handler->GetSession()->GetPlayer();
            Creature* creature = handler->GetSession()->GetPlayer()->GetMap()->GetCreature(ObjectGuid::Create<HighGuid::Creature>(chr->GetMapId(), VISUAL_WAYPOINT, guid));
            if (!creature)
            {
                handler->PSendSysMessage(LANG_WAYPOINT_NOTREMOVED, guid);
                hasError = true;

                WorldDatabasePreparedStatement* stmt = WorldDatabase.GetPreparedStatement(WORLD_DEL_CREATURE);

                stmt->setUInt64(0, guid);

                WorldDatabase.Execute(stmt);
            }
            else
            {
                creature->CombatStop();
                creature->DeleteFromDB();
                creature->AddObjectToRemoveList();
            }
        }
        while (result->NextRow());
        // set "wpguid" column to "empty" - no visual waypoint spawned
        stmt = WorldDatabase.GetPreparedStatement(WORLD_UPD_WAYPOINT_DATA_ALL_WPGUID);

        WorldDatabase.Execute(stmt);
        //WorldDatabase.PExecute("UPDATE creature_movement SET wpguid = '0' WHERE wpguid <> '0'");

        if (hasError)
        {
            handler->PSendSysMessage(LANG_WAYPOINT_TOOFAR1);
            handler->PSendSysMessage(LANG_WAYPOINT_TOOFAR2);
            handler->PSendSysMessage(LANG_WAYPOINT_TOOFAR3);
        }

        handler->SendSysMessage(LANG_WAYPOINT_VP_ALLREMOVED);
        return true;
    }

    handler->PSendSysMessage("|cffff33ffDEBUG: wpshow - no valid command found|r");
    return true;
}

