static bool HandleAccountSetGmLevelCommand(ChatHandler* handler, char const* args)
{
    if (!*args)
        return false;

    std::string targetAccountName;
    uint32 targetAccountId = 0;
    uint32 targetSecurity = 0;
    uint32 gm = 0;
    char* arg1 = strtok((char*)args, " ");
    char* arg2 = strtok(NULL, " ");
    char* arg3 = strtok(NULL, " ");
    bool isAccountNameGiven = true;

    if (arg1 && !arg3)
    {
        if (!handler->getSelectedPlayer())
            return false;
        isAccountNameGiven = false;
    }

    // Check for second parameter
    if (!isAccountNameGiven && !arg2)
        return false;

    // Check for account
    if (isAccountNameGiven)
    {
        targetAccountName = arg1;
        if (!Utf8ToUpperOnlyLatin(targetAccountName))
        {
            handler->PSendSysMessage(LANG_ACCOUNT_NOT_EXIST, targetAccountName.c_str());
            handler->SetSentErrorMessage(true);
            return false;
        }
    }

    // Check for invalid specified GM level.
    gm = (isAccountNameGiven) ? atoi(arg2) : atoi(arg1);
    if (gm > SEC_CONSOLE)
    {
        handler->SendSysMessage(LANG_BAD_VALUE);
        handler->SetSentErrorMessage(true);
        return false;
    }

    // handler->getSession() == NULL only for console
    targetAccountId = (isAccountNameGiven) ? AccountMgr::GetId(targetAccountName) : handler->getSelectedPlayer()->GetSession()->GetAccountId();
    int32 gmRealmID = (isAccountNameGiven) ? atoi(arg3) : atoi(arg2);
    uint32 playerSecurity;
    if (handler->GetSession())
        playerSecurity = AccountMgr::GetSecurity(handler->GetSession()->GetAccountId(), gmRealmID);
    else
        playerSecurity = SEC_CONSOLE;

    // can set security level only for target with less security and to less security that we have
    // This is also reject self apply in fact
    targetSecurity = AccountMgr::GetSecurity(targetAccountId, gmRealmID);
    if (targetSecurity >= playerSecurity || gm >= playerSecurity)
    {
        handler->SendSysMessage(LANG_YOURS_SECURITY_IS_LOW);
        handler->SetSentErrorMessage(true);
        return false;
    }

    // Check and abort if the target gm has a higher rank on one of the realms and the new realm is -1
    if (gmRealmID == -1 && !AccountMgr::IsConsoleAccount(playerSecurity))
    {
        LoginDatabasePreparedStatement* stmt = LoginDatabase.GetPreparedStatement(LOGIN_SEL_ACCOUNT_ACCESS_GMLEVEL_TEST);

        stmt->setUInt32(0, targetAccountId);
        stmt->setUInt8(1, uint8(gm));

        PreparedQueryResult result = LoginDatabase.Query(stmt);

        if (result)
        {
            handler->SendSysMessage(LANG_YOURS_SECURITY_IS_LOW);
            handler->SetSentErrorMessage(true);
            return false;
        }
    }

    // Check if provided realmID has a negative value other than -1
    if (gmRealmID < -1)
    {
        handler->SendSysMessage(LANG_INVALID_REALMID);
        handler->SetSentErrorMessage(true);
        return false;
    }

    // If gmRealmID is -1, delete all values for the account id, else, insert values for the specific realmID

    if (gmRealmID == -1)
    {
        LoginDatabasePreparedStatement* stmt = LoginDatabase.GetPreparedStatement(LOGIN_DEL_ACCOUNT_ACCESS);
        stmt->setUInt32(0, targetAccountId);
        LoginDatabase.Execute(stmt);
    }
    else
    {
        LoginDatabasePreparedStatement* stmt = LoginDatabase.GetPreparedStatement(LOGIN_DEL_ACCOUNT_ACCESS_BY_REALM);
        stmt->setUInt32(0, targetAccountId);
        stmt->setUInt32(1, realm.Id.Realm);
        LoginDatabase.Execute(stmt);
    }

    if (gm != 0)
    {
        LoginDatabasePreparedStatement* stmt = LoginDatabase.GetPreparedStatement(LOGIN_INS_ACCOUNT_ACCESS);

        stmt->setUInt32(0, targetAccountId);
        stmt->setUInt8(1, uint8(gm));
        stmt->setInt32(2, gmRealmID);

        LoginDatabase.Execute(stmt);
    }


    handler->PSendSysMessage(LANG_YOU_CHANGE_SECURITY, targetAccountName.c_str(), gm);
    return true;
}

