    if (!target->HasTitle(target->GetInt32Value(PLAYER_FIELD_PLAYER_TITLE)))
    {
        target->SetUInt32Value(PLAYER_FIELD_PLAYER_TITLE, 0);
        handler->PSendSysMessage(LANG_CURRENT_TITLE_RESET, handler->GetNameLink(target).c_str());
    }

    return true;
}

