    if (!std::isfinite(preciseAmount) || preciseAmount < std::numeric_limits<int32>::min() ||
        preciseAmount > std::numeric_limits<int32>::max())
        return false;

    target->ModifyCurrency(currencyType->ID, int32(preciseAmount), true, true, false, false);

    return true;
}

